// Generated from src/registry/sources/control-ui/recipes/morphing-panel.css by scripts/gen-knob-contracts.ts — run `bun run sync:knobs`.
export const morphingPanelKnobs = [
  "--cui-morphing-panel-radius",
  "--cui-morphing-panel-background",
  "--cui-morphing-panel-foreground",
  "--cui-morphing-panel-border-color",
  "--cui-morphing-panel-shadow",
  "--cui-morphing-panel-trigger-hover-background",
] as const;
export type MorphingPanelKnobStyle = Partial<Record<(typeof morphingPanelKnobs)[number], string>>;

@layer components {
  :where([data-control-family="morphing-panel"][data-slot="root"]) {
    --cui-morphing-panel-radius: var(--radius-control);
    --cui-morphing-panel-background: var(--card);
    --cui-morphing-panel-foreground: var(--card-foreground);
    --cui-morphing-panel-border-color: oklch(from var(--border) l c h / 0.8);
    --cui-morphing-panel-shadow: var(--shadow-md);
    --cui-morphing-panel-trigger-hover-background: oklch(from var(--foreground) l c h / 0.06);
    border-radius: var(--cui-morphing-panel-radius);
    background-color: var(--cui-morphing-panel-background);
    color: var(--cui-morphing-panel-foreground);
    box-shadow:
      var(--cui-morphing-panel-shadow),
      0 0 0 1px var(--cui-morphing-panel-border-color);
    transition-property: width, height, border-radius, box-shadow;
    transition-duration: var(--duration-slow);
    transition-timing-function: var(--ease-emphasized);
  }

  :where([data-control-family="morphing-panel"][data-slot="root"][data-state="open"]) {
    --cui-morphing-panel-radius: var(--radius-panel);
    --cui-morphing-panel-shadow: var(--shadow-pop);
  }

  :where([data-control-ui="morphing-panel"][data-slot="trigger"]) {
    border-radius: inherit;
    outline: none;
    color: currentColor;
    font-size: var(--text-body);
    font-weight: 500;
    transition-property: top, right, width, height, border-radius, padding, color, background-color, box-shadow;
    transition-duration: var(--duration-slow);
    transition-timing-function: var(--ease-emphasized);
  }

  :where([data-control-ui="morphing-panel"][data-slot="trigger"][data-state="open"]) {
    border-radius: var(--radius-control);
  }

  @media (hover: hover) {
    :where([data-control-ui="morphing-panel"][data-slot="trigger"]:hover) {
      background-color: var(--cui-morphing-panel-trigger-hover-background);
    }
  }

  :where([data-control-ui="morphing-panel"][data-slot="trigger"] > svg) {
    transition-property: rotate;
    transition-duration: var(--duration-base);
    transition-timing-function: var(--ease-emphasized);
  }

  :where([data-control-ui="morphing-panel"][data-slot="trigger"][data-state="open"] > svg) {
    rotate: 45deg;
  }

  :where([data-control-family="morphing-panel"][data-slot="content"]) {
    --_morphing-panel-content-hidden-translate: --spacing(1);
    border-radius: inherit;
    outline: none;
    opacity: 1;
    filter: blur(0);
    translate: 0 0;
    transition-property: opacity, filter, translate;
    transition-duration: var(--duration-base);
    transition-timing-function: var(--ease-standard);
  }

  :where(
    [data-control-family="morphing-panel"][data-slot="content"][data-starting-style],
    [data-control-family="morphing-panel"][data-slot="content"][data-ending-style]
  ) {
    opacity: 0;
    filter: blur(var(--blur-sm));
    translate: 0 calc(var(--_morphing-panel-content-hidden-translate) * -1);
  }
}

@property --cui-morphing-panel-radius {
  syntax: "<length-percentage>";
  inherits: true;
  initial-value: 0px;
}

@property --cui-morphing-panel-background {
  syntax: "<color>";
  inherits: true;
  initial-value: transparent;
}

@property --cui-morphing-panel-foreground {
  syntax: "<color>";
  inherits: true;
  initial-value: transparent;
}

@property --cui-morphing-panel-border-color {
  syntax: "<color>";
  inherits: true;
  initial-value: transparent;
}

@property --cui-morphing-panel-shadow {
  syntax: "*";
  inherits: true;
}

@property --cui-morphing-panel-trigger-hover-background {
  syntax: "<color>";
  inherits: true;
  initial-value: transparent;
}

"use client";

import { Collapsible as CollapsiblePrimitive } from "@base-ui/react/collapsible";
import { useRender } from "@base-ui/react/use-render";
import type { ComponentProps, CSSProperties, ReactNode } from "react";
import type { MorphingPanelKnobStyle } from "@/components/control-ui/knob-contracts/morphing-panel-knobs";
import { cn } from "@/components/control-ui/lib/cn";
import type { CollapsibleContentProps, CollapsibleProps, CollapsibleTriggerProps } from "@/components/control-ui/ui/collapsible";

export type MorphingPanelDimensions = { width: string; height: string };

export type MorphingPanelProps = Omit<CollapsibleProps, "style"> & {
  collapsedSize: MorphingPanelDimensions;
  expandedSize: MorphingPanelDimensions;
  style?: CSSProperties & MorphingPanelKnobStyle;
};

export type MorphingPanelTriggerProps = Omit<CollapsibleTriggerProps, "style"> & {
  style?: CSSProperties & MorphingPanelKnobStyle;
};

export type MorphingPanelContentProps = Omit<CollapsibleContentProps, "style"> & {
  style?: CSSProperties & MorphingPanelKnobStyle;
};

type MorphingPanelStyle = CSSProperties & {
  "--_morphing-panel-collapsed-height": string;
  "--_morphing-panel-collapsed-width": string;
  "--_morphing-panel-expanded-height": string;
  "--_morphing-panel-expanded-width": string;
};

function MorphingPanelTriggerElement({
  triggerProps,
  open,
  render,
  className,
  children,
}: {
  triggerProps: ComponentProps<"button">;
  open: boolean;
  render: MorphingPanelTriggerProps["render"];
  className?: string;
  children: ReactNode;
}) {
  const panelState = open ? "open" : "closed";

  return useRender({
    defaultTagName: "button",
    render,
    state: { open },
    props: {
      ...triggerProps,
      "data-control-ui": "morphing-panel",
      "data-slot": "trigger",
      "data-state": panelState,
      className: cn(triggerProps.className, className),
      children,
    },
  });
}

export function MorphingPanel({ collapsedSize, expandedSize, className, style, ...props }: MorphingPanelProps) {
  const dimensions = {
    "--_morphing-panel-collapsed-height": collapsedSize.height,
    "--_morphing-panel-collapsed-width": collapsedSize.width,
    "--_morphing-panel-expanded-height": expandedSize.height,
    "--_morphing-panel-expanded-width": expandedSize.width,
    ...style,
  } satisfies MorphingPanelStyle;

  return (
    <CollapsiblePrimitive.Root
      className={className}
      style={dimensions}
      render={(renderProps, state) => {
        const panelState = state.open ? "open" : "closed";
        const panelSize = state.open ? "expanded" : "collapsed";
        const panelStyle: CSSProperties = {
          ...renderProps.style,
          height: `var(--_morphing-panel-${panelSize}-height)`,
          width: `min(var(--_morphing-panel-${panelSize}-width), 100%)`,
        };
        return (
          <div
            {...renderProps}
            data-control-ui="morphing-panel"
            data-control-family="morphing-panel"
            data-slot="root"
            data-state={panelState}
            data-surface="panel"
            style={panelStyle}
            className={cn("relative isolate max-w-full overflow-hidden", renderProps.className)}
          />
        );
      }}
      {...props}
    />
  );
}

export function MorphingPanelTrigger({ render, className, children, ...props }: MorphingPanelTriggerProps) {
  return (
    <CollapsiblePrimitive.Trigger
      className="group/morphing-panel-trigger absolute top-0 right-0 z-10 flex size-full cursor-pointer items-center justify-between gap-2 px-4 data-[state=open]:top-2 data-[state=open]:right-2 data-[state=open]:size-9 data-[state=open]:justify-center data-[state=open]:p-0 pointer-coarse:data-[state=open]:size-11 [&>svg]:shrink-0"
      {...props}
      render={(triggerProps, state) => (
        <MorphingPanelTriggerElement triggerProps={triggerProps} open={state.open} render={render} className={className}>
          {children}
        </MorphingPanelTriggerElement>
      )}
    />
  );
}

export function MorphingPanelContent({ className, ...props }: MorphingPanelContentProps) {
  return (
    <CollapsiblePrimitive.Panel
      className={className}
      render={(renderProps, state) => {
        const panelState = state.open ? "open" : "closed";
        return (
          <div
            {...renderProps}
            data-control-ui="morphing-panel"
            data-control-family="morphing-panel"
            data-slot="content"
            data-state={panelState}
            className={cn("absolute inset-0 overflow-hidden", renderProps.className)}
          />
        );
      }}
      {...props}
    />
  );
}
